import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        List<String> names = List.of("Aman", "Priya", "Ravi", "Anita");
        List<String> result = names.stream()
            .filter(n -> n.startsWith("A"))
            .map(String::toUpperCase)
            .sorted()
            .collect(Collectors.toList());
        System.out.println(result);
        System.out.println(names.stream().mapToInt(String::length).summaryStatistics().getMax());
        Map<Character, Long> grouped = names.stream()
            .collect(Collectors.groupingBy(n -> n.charAt(0), TreeMap::new, Collectors.counting()));
        System.out.println(grouped);
    }
}

import java.util.*;

public class Main {
    static Optional<Integer> parse(String text) {
        try {
            return Optional.of(Integer.parseInt(text));
        } catch (NumberFormatException e) {
            return Optional.empty();
        }
    }

    public static void main(String[] args) {
        List<String> raw = List.of("4", "x", "6");
        int total = raw.stream()
            .map(Main::parse)
            .flatMap(Optional::stream)
            .reduce(0, Integer::sum);
        System.out.println(total);
        System.out.println(parse("x").orElse(-1));
        System.out.println(parse("7").map(n -> n * 2).orElse(0));
    }
}

