import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Integer> nums = new ArrayList<>();
        for (int i = 0; i < n; i++) nums.add(sc.nextInt());
        int total = nums.stream()
            .filter(v -> v % 2 == 0)
            .mapToInt(v -> v * v)
            .sum();
        System.out.println(total);
    }
}
